        $kind = strtoupper($statement->tokens()[0]->text);
        $targets = $this->targets($statement, $id);
        $scope = new Scope($this->context->tables->identifiers, $targets, queries: $this->context);
        $assignments = [];
        foreach (Tree::outer($statement, ['set_clause', 'update_elem', 'setlist']) as $assignment) {
