declare(strict_types=1);

namespace Fuzz\\Target;

use Error;
use SqlSemantics\\Binder;
use Throwable;

/**
 * The total-analysis property for arbitrary SQL generated from the complete grammar.
 */
final class SemanticsTarget
{
    public function __construct(public readonly Binder $binder)
    {
    }

    public function verify(string $sql, string $input): void
    {
        try {
            $analysis = $this->binder->analyze($sql);
            if ($sql === '' || $analysis->statement->source->toString() !== $sql) {
                throw new Error('Analysis lost the original statement.');
            }
            (new GraphProperties($this->binder->schema->dialect))->statement($analysis->statement);
            if (serialize($analysis) !== serialize($this->binder->analyze($sql))) {
                throw new Error('Semantic analysis is not deterministic.');
            }
            if ($analysis->diagnostics === [] && serialize($analysis->statement) !== serialize($this->binder->bind($sql))) {
                throw new Error('Diagnostic-free analysis disagrees with strict binding.');
            }
        } catch (Throwable $error) {
            throw new Error('Semantic property failed for ' . $this->binder->schema->grammarVersion . "\\nInput hex: " . bin2hex($input) . "\\nSQL:\\n" . $sql . "\\n" . $error->getMessage(), 0, $error);
        }
    }
}
''')
put('fuzz/Target/GraphProperties.php', '''<?php

declare(strict_types=1);

namespace Fuzz\\Target;

use Error;
use SqlSemantics\\Dialect;
use SqlSemantics\\Model\\BoundStatement;
use SqlSemantics\\Model\\Expression;
use SqlSemantics\\Model\\ExpressionKind;

/**
 * Checks semantic graph invariants independently of the grammar generator.
 */
final class GraphProperties
{
    public function __construct(public readonly Dialect $dialect)
    {
    }

    public function statement(BoundStatement $statement): void
    {
        if ($statement->kind === '' || $statement->scopeId === '') {
            throw new Error('A statement must have an operation and a scope.');
        }
        foreach ($statement->outputs as $ordinal => $output) {
            if ($output->ordinal !== $ordinal) {
                throw new Error('Output ordinals do not preserve projection order.');
            }
            $this->expression($output->expression);
        }
        foreach ([$statement->where, $statement->having, $statement->limit, $statement->offset] as $expression) {
            if ($expression !== null) {
                $this->expression($expression);
            }
        }
        foreach ([...$statement->groupBy, ...array_values($statement->assignments), ...array_merge([], ...$statement->rows), ...array_merge([], ...array_values($statement->clauses))] as $expression) {
            $this->expression($expression);
        }
        foreach ($statement->orderBy as $ordering) {
            $this->expression($ordering->expression);
        }
        foreach ([...array_values($statement->ctes), ...$statement->branches, ...$statement->queries] as $query) {
            $this->statement($query);
        }
        foreach ([...$statement->relations, ...$statement->targets] as $relation) {
            if ($relation->scopeId !== $statement->scopeId) {
                throw new Error('A relation belongs to the wrong scope.');
            }
            if ($relation->query !== null) {
                $this->statement($relation->query);
            }
        }
    }

    public function expression(Expression $expression): void
    {
        if ($expression->type->dialect !== $this->dialect || $expression->type->name === '') {
            throw new Error('An expression has an invalid type descriptor.');
        }
        if ($expression->kind === ExpressionKind::Column && $expression->binding === null) {
            throw new Error('A resolved column is missing its declaration.');
        }
        if ($expression->kind === ExpressionKind::UnresolvedColumn && ($expression->reference === [] || $expression->binding !== null || $expression->type->name !== 'unknown')) {
            throw new Error('An unresolved reference was lost or assigned a fabricated type.');
        }
        if ($expression->binding !== null && !in_array($expression->binding->column, $expression->binding->table->columns, true)) {
            throw new Error('A column binding points outside its declaration.');
        }
        foreach ($expression->operands as $operand) {
            $this->expression($operand);
        }
        if ($expression->query !== null) {
            $this->statement($expression->query);
        }
    }
}
''')
