    public function parse(array $tokens): ?Node
    {
        $pending = [new ParseBranch()];
        $seen = [];
        while ($pending !== []) {
            $branch = array_pop($pending);
            while (isset($tokens[$branch->index])) {
                $state = $branch->states[count($branch->states) - 1];
                $token = $tokens[$branch->index];
