declare(strict_types=1);

namespace SqlSemantics\Model\Write;

use InvalidArgumentException;
use SqlSemantics\Model\Expression;
use SqlSemantics\Model\ExpressionKind;
use SqlSemantics\Model\TableUse;

/**
 * Ordered storage destinations for an INSERT, independent of table declaration order.
 *
 * @visibility public
 */
final class Insertion
{
    /**
     * @param TableUse $target Destination relation
     * @param list<Expression> $columns Destination of each input position, including unresolved references
     * @param bool $explicitColumns Whether SQL supplied a target column list
     * @param bool $defaultValues Whether a single row of defaults was requested
     * @param list<\SqlSemantics\Schema\ColumnDefinition> $omittedColumns Columns supplied by defaults or generated values
     */
    public function __construct(
        public readonly TableUse $target,
        public readonly array $columns,
        public readonly bool $explicitColumns,
        public readonly bool $defaultValues,
        public readonly array $omittedColumns = [],
    ) {
        foreach ($columns as $column) {
            if (!in_array($column->kind, [ExpressionKind::Column, ExpressionKind::UnresolvedColumn], true)) {
                throw new InvalidArgumentException('An insertion destination must be a column reference.');
            }
            if ($column->binding !== null && $column->binding->relationId !== $target->id) {
                throw new InvalidArgumentException('An insertion column belongs to another relation.');
            }
        }
    }
}
''',
'Model/Write/Assignment.php':r'''<?php

declare(strict_types=1);

namespace SqlSemantics\Model\Write;

use InvalidArgumentException;
use SqlParser\Parser\Node;
use SqlSemantics\Model\Expression;

/**
 * One ordered assignment, retaining tuple destinations and their shared value expression.
 *
 * @visibility public
 */
final class Assignment
{
    /**
     * @param non-empty-list<Expression> $targets Resolved or explicitly unresolved storage references
     * @param Expression $value Scalar, row, DEFAULT, or subquery value
     * @param Node $source Assignment syntax, including subscripted destinations
     */
    public function __construct(
        public readonly array $targets,
        public readonly Expression $value,
        public readonly Node $source,
    ) {
        if ($targets === []) {
            throw new InvalidArgumentException('An assignment requires a destination.');
        }
        foreach ($targets as $target) {
            if ($target->type->dialect !== $value->type->dialect) {
                throw new InvalidArgumentException('Assignment destinations and values must use the same dialect.');
            }
        }
    }
}
''',
'Model/Write/ConflictAction.php':r'''<?php

declare(strict_types=1);

namespace SqlSemantics\Model\Write;

use InvalidArgumentException;
use SqlParser\Parser\Node;
use SqlSemantics\Model\Expression;

/**
 * Conflict handling is a separate conditional write stage, not the INSERT row filter.
 *
 * @visibility public
 */
final class ConflictAction
{
    /**
     * @param string $action nothing, update, or replace
     * @param list<Expression> $keys Conflict index expressions
     * @param string|null $constraint Named conflict constraint
     * @param Expression|null $indexPredicate Partial-index inference predicate
     * @param list<Assignment> $assignments Ordered conflict-update assignments
     * @param Expression|null $where Conflict-update row predicate
     * @param Node $source Original conflict clause
     */
    public function __construct(
        public readonly string $action,
        public readonly array $keys,
        public readonly ?string $constraint,
        public readonly ?Expression $indexPredicate,
        public readonly array $assignments,
        public readonly ?Expression $where,
        public readonly Node $source,
    ) {
        if (!in_array($action, ['nothing', 'update', 'replace'], true)) {
            throw new InvalidArgumentException('Invalid conflict action.');
        }
        if ($action !== 'update' && ($assignments !== [] || $where !== null)) {
            throw new InvalidArgumentException('Only a conflict UPDATE can carry assignments or a row predicate.');
        }
    }
}
''',
