'Model/Validation/ExpressionInvariant.php':r'''<?php

declare(strict_types=1);

namespace SqlSemantics\Model\Validation;

use InvalidArgumentException;
use SqlSemantics\Model\Expression;
use SqlSemantics\Model\ExpressionKind;

/**
 * Enforces representation invariants at construction, independently of SQL validity diagnostics.
 *
 * @visibility SqlSemantics
 */
final class ExpressionInvariant
{
    /**
     * Rejects inconsistent reference states and mixed-dialect expression graphs.
     */
    public static function check(Expression $expression): void
    {
        if (($expression->kind === ExpressionKind::Column) !== ($expression->binding !== null)) {
            throw new InvalidArgumentException('A resolved column must have exactly one column binding.');
        }
        if ($expression->kind === ExpressionKind::UnresolvedColumn && ($expression->reference === [] || $expression->type->name !== 'unknown')) {
            throw new InvalidArgumentException('An unresolved column must retain its name and unknown type.');
        }
        foreach ($expression->operands as $operand) {
            if ($operand->type->dialect !== $expression->type->dialect) {
                throw new InvalidArgumentException('An expression cannot mix SQL dialects.');
            }
        }
        if ($expression->kind === ExpressionKind::Subquery && $expression->query === null) {
            throw new InvalidArgumentException('A subquery expression must retain its query.');
        }
        if ($expression->kind === ExpressionKind::DefaultValue && $expression->operands !== []) {
            throw new InvalidArgumentException('DEFAULT is a storage instruction without operands.');
        }
    }
}
''',
'Model/Validation/StatementInvariant.php':r'''<?php

declare(strict_types=1);

namespace SqlSemantics\Model\Validation;

use InvalidArgumentException;
use SqlSemantics\Model\BoundStatement;

/**
 * Keeps output order and relation ownership valid for every constructed statement.
 *
 * @visibility SqlSemantics
 */
final class StatementInvariant
{
    /**
     * Validates representation, allowing diagnosed invalid SQL to remain representable.
     */
    public static function check(BoundStatement $statement): void
    {
        if ($statement->scopeId === '' || $statement->kind === '') {
            throw new InvalidArgumentException('A statement requires a scope and operation.');
        }
        foreach ($statement->outputs as $ordinal => $output) {
            if ($output->ordinal !== $ordinal) {
                throw new InvalidArgumentException('Output positions must be contiguous and ordered.');
            }
        }
