<?php

declare(strict_types=1);

namespace SqlSemantics\Model\Validation;

use InvalidArgumentException;

/**
 * Enforces collection element types that PHP's native array type cannot express.
 *
 * @visibility SqlSemantics
 */
final class Collections
{
    /**
     * @param array<array-key, mixed> $values Runtime collection
     * @param class-string $class Required element class
     * @throws InvalidArgumentException
     */
    public static function objects(array $values, string $class, bool $list = true): void
    {
        if ($list && !array_is_list($values)) {
            throw new InvalidArgumentException('An ordered semantic collection must be a list.');
        }
        foreach ($values as $value) {
            if (!$value instanceof $class) {
                throw new InvalidArgumentException('A semantic collection contains an invalid element type.');
            }
        }
    }

    /**
     * @param array<array-key, mixed> $values Runtime name parts or identity list
     * @throws InvalidArgumentException
     */
    public static function strings(array $values): void
    {
        if (!array_is_list($values)) {
            throw new InvalidArgumentException('An ordered name or identity collection must be a list.');
        }
        foreach ($values as $value) {
            if (!is_string($value)) {
                throw new InvalidArgumentException('Name parts and identities must be strings.');
            }
        }
    }
}
