+    }
+
+    /**
+     * @param list<Expression> $arguments
+     */
+    public static function score(FunctionSignature $signature, array $arguments): ?int
+    {
+        if (!self::arity($signature, count($arguments))) {
+            return null;
+        }
+        $score = $signature->parameters === null ? 0 : 1;
