 *
 * @visibility SqlSemantics
 */
final class FunctionRules
{
    /** @param list<Expression> $operands */
    public function bind(string $name, array $operands, Node $source, Scope $scope): Expression
    {
        if (in_array($name, ['COALESCE', 'NULLIF'], true)) {
