            if ($type !== null && $type->name !== 'unknown') {
                $operands[$index] = $rules->coerce($operand, $type);
            }
        }
        return $operands;
    }

    /** @param list<Expression> $operands */
    public function nullability(FunctionSignature $signature, array $operands): Nullability
    {
