namespace SqlSemantics\Model\Transformation;

use SqlParser\Lexer\Token;
use SqlParser\Parser\Node;
use SqlSemantics\Model\Sql\Tree;

/**
 * Replaces one owned structural component, without editing SQL text or byte ranges.
 *
 * @visibility SqlSemantics
 */
final class SourceEdit
{
    /**
     * Returns an independent tree; untouched components remain safely shared.
     */
    public static function replace(Node|Token $source, Tree $tree, Node|Token $target, Tree $replacement): Tree
    {
        if ($source === $target) {
            return $replacement;
        }
        if ($source instanceof Token) {
            return $tree;
        }
        $children = $tree->children;
        foreach ($source->children as $index => $child) {
            $part = $children[$index] ?? null;
            if ($part instanceof Tree) {
                $children[$index] = self::replace($child, $part, $target, $replacement);
            }
        }
        return new Tree($tree->role, $children);
    }
}
