<?php

declare(strict_types=1);

namespace SqlSemantics\Serialization;

use SqlSemantics\Model\BoundQuery;
use SqlSemantics\Model\BoundSelect;
use SqlSemantics\Model\Statement;
use SqlSemantics\Model\Sql\Build;
use SqlSemantics\Model\Sql\Parts;
use SqlSemantics\Model\Sql\Tree;
use SqlSemantics\Model\Validation\InvalidStructure;

/** Writes query stages in their SQL evaluation structure. @visibility SqlSemantics */
final class Queries
{
    public static function write(BoundQuery $query): Tree
    {
        if ($query instanceof BoundSelect) {
            $body = new Tree('select', [Build::keyword($query->distinct ? 'SELECT DISTINCT' : 'SELECT'), Parts::outputs($query->outputs, $query->origin->dialect), ...($query->from === null ? [] : [Build::keyword('FROM'), Relations::write($query->from, $query->origin->dialect)]), Parts::expressions('WHERE', $query->where === null ? [] : [$query->where]), Parts::expressions('GROUP BY', $query->groupBy), Parts::expressions('HAVING', $query->having === null ? [] : [$query->having])]);
        } elseif ($query instanceof Statement\ValuesStatement) {
            $body = Parts::rows($query->rows);
        } elseif ($query instanceof Statement\CompoundStatement) {
            $body = Build::separated(array_map(static fn (BoundQuery $branch): Tree => self::operand($branch), $query->branches), $query->setOperator->value);
        } elseif ($query instanceof Statement\TableStatement) {
            $body = new Tree('table', [Build::keyword('TABLE'), Relations::write($query->from, $query->origin->dialect)]);
        } else {
            throw new InvalidStructure('A relation description cannot be serialized as a standalone query.');
        }
        return new Tree('query', [QueryParts::with($query->ctes, $query->origin->dialect), $body, Parts::ordering($query->orderBy), QueryParts::pagination($query->limit, $query->offset, $query->withTies, $query->origin->dialect)]);
    }

    public static function operand(BoundQuery $query): Tree
    {
        if ($query instanceof BoundSelect || $query instanceof Statement\ValuesStatement || $query instanceof Statement\CompoundStatement || $query instanceof Statement\TableStatement) {
            $body = self::write($query);
            if ($query instanceof Statement\CompoundStatement || $query->ctes !== [] || $query->orderBy !== [] || $query->limit !== null || $query->offset !== null) {
                return $query->origin->dialect === \SqlSemantics\Dialect::Sqlite ? new Tree('operand', [Build::keyword('SELECT * FROM'), Build::parentheses($body)]) : Build::parentheses($body);
            }
            return $body;
        }
        throw new InvalidStructure('A set operand requires a query expression.');
    }
}
