<?php

declare(strict_types=1);

namespace SqlSemantics\Serialization;

use SqlSemantics\Dialect;
use SqlSemantics\Model\Join;
use SqlSemantics\Model\JoinKind;
use SqlSemantics\Model\TableUse;
use SqlSemantics\Model\Sql\Build;
use SqlSemantics\Model\Sql\Tree;

/** Writes relation identities and join operands. @visibility SqlSemantics */
final class Relations
{
    public static function write(TableUse|Join $relation, Dialect $dialect): Tree
    {
        if ($relation instanceof Join) {
            $kind = match ($relation->kind) {
                JoinKind::Inner => 'INNER JOIN', JoinKind::Left => 'LEFT JOIN', JoinKind::Right => 'RIGHT JOIN', JoinKind::Full => 'FULL JOIN', JoinKind::Cross => 'CROSS JOIN',
            };
            return new Tree('join', [self::write($relation->left, $dialect), Build::keyword($kind), $relation->right instanceof Join ? Build::parentheses(self::write($relation->right, $dialect)) : self::write($relation->right, $dialect), ...($relation->condition === null ? [] : [Build::keyword('ON'), Expressions::write($relation->condition)])]);
        }
        $table = $relation->declaration;
        $name = $table->schema === '' ? [$table->name] : [$table->schema, $table->name];
        $body = $relation->query === null ? Build::identifier($name, $dialect) : Build::parentheses(Queries::write($relation->query));
        return new Tree('relation', [$body, ...($relation->alias === null ? [] : [Build::keyword('AS'), Build::identifier([$relation->alias], $dialect)])]);
    }

    public static function target(TableUse $table, Dialect $dialect): Tree
    {
        $declaration = $table->declaration;
        return Build::identifier($declaration->schema === '' ? [$declaration->name] : [$declaration->schema, $declaration->name], $dialect);
    }
