<?php

declare(strict_types=1);

namespace SqlSemantics\Serialization;

use SqlSemantics\Dialect;
use SqlSemantics\Model\Join;
use SqlSemantics\Model\Statement\UpdateStatement;
use SqlSemantics\Model\Statement\DeleteStatement;
use SqlSemantics\Model\Sql\Build;
use SqlSemantics\Model\Sql\Parts;
use SqlSemantics\Model\Sql\Tree;
use SqlSemantics\Model\Validation\InvalidStructure;

/** Writes mutation targets separately from read-only input relations. @visibility SqlSemantics */
final class Mutations
{
    public static function write(UpdateStatement|DeleteStatement $statement): Tree
    {
        $dialect = $statement->origin->dialect;
        if ($statement->targets === [] || $statement->from === null) {
            throw new InvalidStructure('A mutation requires its target relation.');
        }
        $target = $statement->targets[0];
        $from = $statement->from;
        if ($statement instanceof UpdateStatement) {
            $parts = [Build::keyword('UPDATE'), Relations::write($dialect === Dialect::MySql ? $from : $target, $dialect), Build::keyword('SET'), Write\Assignments::write($statement->writes)];
        } else {
            $names = array_map(static fn ($table): Tree => Build::identifier([$table->alias ?? $table->declaration->name], $dialect), $statement->targets);
            $parts = $dialect === Dialect::MySql && $from instanceof Join
                ? [Build::keyword('DELETE'), Build::separated($names), Build::keyword('FROM'), Relations::write($from, $dialect)]
                : [Build::keyword('DELETE FROM'), Relations::write($target, $dialect)];
        }
        if ($dialect !== Dialect::MySql && $from instanceof Join && $from->left === $target) {
            array_push($parts, Build::keyword($statement instanceof UpdateStatement ? 'FROM' : 'USING'), Relations::write($from->right, $dialect));
        }
        return new Tree('mutation', [QueryParts::with($statement->ctes, $dialect), ...$parts, Parts::expressions('WHERE', $statement->where === null ? [] : [$statement->where]), Parts::ordering($statement->orderBy), QueryParts::pagination($statement->limit, null, false, $dialect), ...($statement->outputs === [] ? [] : [Build::keyword('RETURNING'), Parts::outputs($statement->outputs, $dialect)])]);
    }
}
