<?php

declare(strict_types=1);

namespace SqlSemantics\Model\Transformation;

use ReflectionClass;
use SqlSemantics\Model\BoundStatement;
use SqlSemantics\Model\Expression;
use SqlSemantics\Model\Validation\InvalidStructure;

/** Rebuilds immutable constructor-owned operands, reapplying each concrete invariant. @visibility SqlSemantics */
final class ExpressionEdit
{
    /**
     * @template T of BoundStatement
     * @param T $statement
     * @return T
     */
    public static function replace(BoundStatement $statement, Expression $target, Expression $replacement): BoundStatement
    {
        if (!in_array($target, \SqlSemantics\Model\Traversal\Expressions::all($statement), true)) {
            throw new InvalidStructure('The expression does not belong to this statement.');
        }
        return self::rebuild($statement, $target, $replacement);
    }

    /**
     * @template T of object
     * @param T $object
     * @return T
     */
    public static function rebuild(object $object, Expression $target, Expression $replacement): object
    {
        $reflection = new ReflectionClass($object);
        $constructor = $reflection->getConstructor();
        if ($constructor === null) {
            return $object;
        }
        $properties = get_object_vars($object);
        $arguments = [];
        $changed = false;
        foreach ($constructor->getParameters() as $parameter) {
            $name = $parameter->getName();
            if (!array_key_exists($name, $properties)) {
                throw new InvalidStructure('An immutable semantic operand must be retained: ' . $object::class . '::' . $name);
            }
            $before = $properties[$name];
            $after = self::operand($before, $target, $replacement);
            $arguments[$name] = $after;
            $changed = $changed || $before !== $after;
        }
        if (!$changed) {
            return $object;
        }
        $class = $object::class;
        return new $class(...$arguments);
    }

    public static function operand(mixed $value, Expression $target, Expression $replacement): mixed
    {
        if ($value === $target) {
            return $replacement;
        }
        if (is_array($value)) {
            return array_map(static fn (mixed $element): mixed => self::operand($element, $target, $replacement), $value);
        }
        if (is_object($value) && !$value instanceof \UnitEnum && str_starts_with($value::class, 'SqlSemantics\\Model\\') && !$value instanceof \SqlSemantics\Model\Statement\Origin && !$value instanceof \SqlSemantics\Model\ColumnBinding && !$value instanceof \SqlSemantics\Model\Scalar\ExpressionFacts) {
            return self::rebuild($value, $target, $replacement);
        }
        return $value;
    }
}
