use SqlSemantics\Model\Scalar\Value\ContextValueKind;
use SqlSemantics\Type\TypeDescriptor;
use SqlSemantics\Type\Nullability;

/** Classifies clock/session requests and their optional declared precision. @visibility SqlSemantics */
final class ContextValueBinder
{
    public function bind(Node $node, Scope $scope): ?ContextValue
    {
        $tokens = $node->tokens();
        $first = $tokens[0] ?? null;
        if ($first === null || in_array($first->name, ['IDENT', 'IDENT_QUOTED', 'ID'], true)) {
            return null;
        }
        $kind = ContextValueKind::tryFrom(strtoupper($first->text));
        if ($kind === null) {
            return null;
        }
        $precision = null;
        if (count($tokens) === 4 && $tokens[1]->text === '(' && ctype_digit($tokens[2]->text) && $tokens[3]->text === ')') {
            $precision = (int) $tokens[2]->text;
        } elseif (count($tokens) !== 1 && !(count($tokens) === 3 && $tokens[1]->text === '(' && $tokens[2]->text === ')')) {
            return null;
        }
        $type = match ($kind) {
            ContextValueKind::CurrentDate => 'date',
            ContextValueKind::CurrentTime => $scope->identifiers->dialect === \SqlSemantics\Dialect::PostgreSql ? 'time with time zone' : 'time',
            ContextValueKind::CurrentTimestamp => $scope->identifiers->dialect === \SqlSemantics\Dialect::PostgreSql ? 'timestamp with time zone' : 'timestamp',
            ContextValueKind::LocalTime => 'time', ContextValueKind::LocalTimestamp => 'timestamp',
            default => 'text',
        };
        return new ContextValue(new ExpressionFacts(new TypeDescriptor($scope->identifiers->dialect, $type, $precision === null ? [] : [(string) $precision]), Nullability::NotNull), $node, $kind, $precision);
    }
}
