        if (in_array($kind, ['SAVEPOINT', 'RELEASE'], true) || ($kind === 'ROLLBACK' && in_array('TO', $words, true))) {
            $last = $tokens[count($tokens) - 1];
            $name = $scope->identifiers->name($last);
