                'SAVEPOINT' => new Statement\SavepointStatement($origin, $name),
                'RELEASE' => new Statement\ReleaseSavepointStatement($origin, $name),
                'ROLLBACK' => new Statement\RollbackToSavepointStatement($origin, $name),
