put('Binding/Schema/OptionBinding.php',r'''<?php

declare(strict_types=1);

namespace SqlSemantics\Binding\Schema;

use SqlSemantics\Binding\Statement\UnclassifiedSql;
use SqlSemantics\Model\Relation\QualifiedName;

/**
 * Narrows internal parsed option values into their declared domain types.
 *
 * @visibility SqlSemantics
 */
final class OptionBinding
{
    /**
     * @param array<string, string|bool|list<string>> $options
     */
    public static function string(array $options, string $name): ?string
    {
        $value = $options[$name] ?? null;
        if ($value !== null && !is_string($value)) {
            throw new UnclassifiedSql('Expected a scalar declaration option: ' . $name);
        }
        return $value;
    }

    /**
     * @param array<string, string|bool|list<string>> $options
     */
    public static function integer(array $options, string $name): ?int
    {
        $value = self::string($options, $name);
        if ($value === null) {
            return null;
        }
        $integer = filter_var($value, FILTER_VALIDATE_INT);
        if ($integer === false) {
            throw new UnclassifiedSql('Expected an integer declaration option: ' . $name);
        }
        return $integer;
    }

    /**
     * @param array<string, string|bool|list<string>> $options
     */
    public static function qualified(array $options, string $name): ?QualifiedName
    {
        $value = $options[$name] ?? null;
        if ($value === null) {
            return null;
        }
        if (is_bool($value)) {
            throw new UnclassifiedSql('Expected an identifier declaration option: ' . $name);
        }
        return new QualifiedName(is_string($value) ? [$value] : $value);
    }

    /**
     * @param array<string, string|bool|list<string>> $options
     * @param list<string> $names
     */
    public static function classified(array $options, array $names): void
    {
        $unknown = array_diff(array_keys($options), $names);
        if ($unknown !== []) {
            throw new UnclassifiedSql('Unclassified declaration options: ' . implode(', ', $unknown));
        }
    }
}
''')
put('Binding/Schema/SequenceBinding.php',r'''<?php

declare(strict_types=1);

namespace SqlSemantics\Binding\Schema;

use SqlParser\Parser\Node;
use SqlSemantics\Ast\Tree;
use SqlSemantics\Binding\ExpressionBinder;
use SqlSemantics\Binding\Scope;
use SqlSemantics\Binding\Statement\UnclassifiedSql;
use SqlSemantics\Model\Scalar\Value\Literal;
use SqlSemantics\Schema\Column\SequenceOptions;

/**
 * Classifies sequence values without coercing their arbitrary-precision integers.
 *
 * @visibility SqlSemantics
 */
final class SequenceBinding
{
    /**
     * @param list<Node> $attributes
     */
    public static function read(array $attributes, Scope $scope): SequenceOptions
    {
        $values = [];
        $cycle = null;
        foreach ($attributes as $attribute) {
            foreach (Tree::outer($attribute, ['SeqOptElem']) as $option) {
                $words = array_map(static fn ($token): string => strtoupper($token->text), $option->tokens());
                if (in_array('CYCLE', $words, true)) {
                    $cycle = $words[0] !== 'NO';
                    continue;
                }
                $name = match ($words[0] ?? '') {
                    'START' => 'start', 'INCREMENT' => 'increment', 'MINVALUE' => 'minimum',
                    'MAXVALUE' => 'maximum', 'CACHE' => 'cache',
                    default => throw new UnclassifiedSql('Unclassified sequence option: ' . Tree::text($option)),
                };
                $node = Tree::outer($option, ['NumericOnly'])[0] ?? new Node('sequence_integer', 0, [end($option->children)]);
                $value = (new ExpressionBinder())->bind($node, $scope);
                if (!$value instanceof Literal) {
                    throw new UnclassifiedSql('A sequence option must be an integer literal.');
                }
                $values[$name] = $value;
            }
        }
        return new SequenceOptions($values['start'] ?? null, $values['increment'] ?? null, $values['minimum'] ?? null, $values['maximum'] ?? null, $values['cache'] ?? null, $cycle);
    }
}
''')
