        [$parsed, $constraints] = (new \SqlSemantics\Ast\ColumnReader($context->tables->identifiers))->read($column, Tree::outer($source, ['ccons']));
        $newColumn = new \SqlSemantics\Schema\ColumnDefinition($parsed->name, $parsed->type, $parsed->nullability, $parsed->source);
        $table = new \SqlSemantics\Schema\TableDefinition($target->schema, $target->name, [...$target->columns, $newColumn], $target->constraints, $target->source);
        $scope = new \SqlSemantics\Binding\Scope($context->tables->identifiers, [new \SqlSemantics\Model\Relation\TableReference('declaration', 'declaration', $table, null, $source)], queries: $context);
        return new Statement\AddColumnStatement($origin, $name, \SqlSemantics\Binding\Schema\ColumnBinder::bind($parsed, $scope), array_map(static fn ($constraint): \SqlSemantics\Schema\TableConstraint => \SqlSemantics\Binding\Schema\ConstraintBinder::bind($constraint, $scope), $constraints));
    }
}
