            return new Policy\SqliteInsertion($or === false ? Policy\ConstraintResponse::Default : Policy\ConstraintResponse::from($prefix[$or + 1]));
        }
        if ($dialect === Dialect::MySql) {
            $scheduling = Policy\Scheduling::Default;
            foreach ($prefix as $word) {
                $scheduling = Policy\Scheduling::tryFrom($word) ?? $scheduling;
            }
            return new Policy\MySqlInsertion($scheduling, in_array('IGNORE', $prefix, true));
        }
        $overriding = array_search('OVERRIDING', $words, true);
        return new Policy\PostgreSqlInsertion($overriding === false ? Policy\IdentityOverride::Default : Policy\IdentityOverride::from($words[$overriding + 1]));
