            if (!$query && in_array($child->name, ['SelectStmt', 'select_stmt', 'select', 'query_expression', 'select_with_parens', 'subquery', 'insert_query_expression', 'create_select'], true)) {
                continue;
            }
            $clause = self::find($child, $query);
            if ($clause !== null) {
                return $clause;
            }
        }
        return null;
    }
}
