declare(strict_types=1);

namespace SqlSemantics\Ast\Type;

use SqlParser\Parser\Node;
use SqlSemantics\Ast\Tree;
use SqlSemantics\Binding\Statement\UnclassifiedSql;
use SqlSemantics\Dialect;
use SqlSemantics\Type\Identity;

/**
 * Constructs each built-in family's applicable parameters.
 * @visibility SqlSemantics
 */
final class TypeFamilies
{
    /**
     * @throws UnclassifiedSql
     */
    public static function make(Identity\BuiltinType $base, TypeWords $parts, Dialect $dialect, Node $source): Identity\SqlType
    {
        $parameters = $parts->parameters;
        $first = $parameters[0] ?? null;
        if (count($parameters) > 2) {
            throw new UnclassifiedSql('A built-in type has too many parameter positions: ' . $source->toString());
        }
        if (in_array($base, [Identity\BuiltinType::TinyInt, Identity\BuiltinType::SmallInt, Identity\BuiltinType::MediumInt, Identity\BuiltinType::Integer, Identity\BuiltinType::BigInt, Identity\BuiltinType::Year], true)) {
            return new Identity\IntegerType($base, $first, $parts->unsigned);
        }
        if (in_array($base, [Identity\BuiltinType::Numeric, Identity\BuiltinType::Real, Identity\BuiltinType::Float, Identity\BuiltinType::DoublePrecision], true)) {
            return new Identity\NumericType($base, $first, $parameters[1] ?? null, $parts->unsigned);
        }
        if (in_array($base, [Identity\BuiltinType::Time, Identity\BuiltinType::Timestamp, Identity\BuiltinType::Datetime, Identity\BuiltinType::Timetz, Identity\BuiltinType::Timestamptz], true)) {
            $timezone = str_contains(strtoupper(Tree::text($source)), 'WITHOUT TIME ZONE') ? Identity\TimeZoneMode::Without : (str_contains(strtoupper(Tree::text($source)), 'WITH TIME ZONE') || in_array($base, [Identity\BuiltinType::Timetz, Identity\BuiltinType::Timestamptz], true) ? Identity\TimeZoneMode::With : Identity\TimeZoneMode::Unspecified);
            $base = match ($base) { Identity\BuiltinType::Timetz => Identity\BuiltinType::Time, Identity\BuiltinType::Timestamptz => Identity\BuiltinType::Timestamp, default => $base };
            return new Identity\TemporalType($base, $first, $timezone);
        }
        if (in_array($base, [Identity\BuiltinType::Char, Identity\BuiltinType::Varchar, Identity\BuiltinType::Text, Identity\BuiltinType::TinyText, Identity\BuiltinType::MediumText, Identity\BuiltinType::LongText, Identity\BuiltinType::Binary, Identity\BuiltinType::Varbinary, Identity\BuiltinType::Blob, Identity\BuiltinType::TinyBlob, Identity\BuiltinType::MediumBlob, Identity\BuiltinType::LongBlob, Identity\BuiltinType::Bit, Identity\BuiltinType::Varbit, Identity\BuiltinType::Vector], true)) {
            return new Identity\StringType($base, $first, $parts->characterSet, $parts->binary);
        }
        if ($parameters !== [] || $parts->unsigned || $parts->characterSet !== null || $parts->binary) {
            throw new UnclassifiedSql('Unclassified parameters for ' . $base->value . '.');
        }
        return $base;
    }
}
