{
    /**
     * @throws InvalidStructure
     */
    public static function write(TypeDescriptor $type): Tree
    {
        $identity = $type->identity;
        if ($identity instanceof Identity\BuiltinType) {
            if (in_array($identity, [Identity\BuiltinType::Unknown, Identity\BuiltinType::Dynamic, Identity\BuiltinType::Never, Identity\BuiltinType::Record], true)) {
