            $identity instanceof Identity\NamedType => Type\TypeNames::named($identity, $type->dialect),
            $identity instanceof Identity\ArrayType => Type\TypeNames::array($identity),
            $identity instanceof Identity\EnumType, $identity instanceof Identity\SetType => Type\TypeNames::labels($identity, $type->dialect),
            $identity instanceof Identity\IntegerType => Type\TypeParameters::integer($identity),
            $identity instanceof Identity\NumericType => Type\TypeParameters::numeric($identity),
            $identity instanceof Identity\StringType => Type\TypeParameters::string($identity, $type->dialect),
            $identity instanceof Identity\TemporalType => Type\TypeParameters::temporal($identity),
            $identity instanceof Identity\IntervalType => Type\TypeParameters::interval($identity),
            default => throw new InvalidStructure('Unclassified SQL type identity: ' . $identity::class),
        };
    }
}
