use SqlSemantics\\Model\\Validation\\InputViolation;
use SqlSemantics\\Model\\Validation\\RowShape;
use SqlSemantics\\Type\\Identity\\BuiltinIdentity;

/**
 * Diagnoses row-shape mismatches without evaluating values or cardinality.
 *
 * @visibility SqlSemantics
 */
final class QueryOperandShape
{
    public static function check(Expression $left, Expression $right, Node $source): void
    {
        $a = self::width($left);
        $b = self::width($right);
        if ($a !== null && $b !== null && $a !== $b) {
            throw new InvalidSql(InputViolation::ComparisonWidth, $source);
        }
    }

    public static function width(Expression $value): ?int
    {
        return match (true) {
            $value instanceof RowExpression => count($value->items),
            $value instanceof ScalarSubquery, $value instanceof RowSubquery => RowShape::width($value->query),
            $value->type->identity === BuiltinIdentity::Record, $value->type->identity === BuiltinIdentity::Unknown => null,
            default => 1,
        };
    }
}
