        $member = $statement->outputs[0]->expression;
        self::assertInstanceOf(JsonMembership::class, $member);
        $copy = $member->withFacts($member->facts);
        self::assertSame($member->value, $copy->value);
        self::assertSame($member->array, $copy->array);
    }
}
