use Override;
use SqlParser\Lexer\Token;
use SqlParser\Parser\Node;
use SqlSemantics\Dialect;
use SqlSemantics\Model\Expression;
use SqlSemantics\Model\ExpressionKind;
use SqlSemantics\Model\Scalar\ExpressionFacts;
use SqlSemantics\Model\Validation\InvalidStructure;
use SqlSemantics\Type\Nullability;
use SqlSemantics\Type\TypeDescriptor;

/**
 * Extracts one declared calendar or interval field without evaluating its input.
 * @visibility public
 * @example Inspecting a timestamp extraction
 *     $query = (new \SqlSemantics\Binder((new \SqlSemantics\SchemaBuilder(\SqlSemantics\Dialect::PostgreSql))->build()))->bind('SELECT EXTRACT(YEAR FROM CURRENT_TIMESTAMP)');
 *     $query->outputs[0]->expression->field->value // => 'YEAR'
 */
final class Extract extends Expression
{
    /**
     * Derives the numeric result from the extraction dialect and operand facts.
     * @throws InvalidStructure
     */
    public function __construct(Node|Token $source, public readonly PostgreSqlField|MySqlUnit $field, public readonly Expression $value)
    {
        $dialect = $field instanceof PostgreSqlField ? Dialect::PostgreSql : Dialect::MySql;
        if ($value->type->dialect !== $dialect) {
            throw new InvalidStructure('The extraction field and operand must use the same SQL dialect.');
        }
        $nullable = $value->nullability === Nullability::NotNull ? Nullability::MaybeNull : $value->nullability;
        parent::__construct(new ExpressionFacts(TypeDescriptor::builtin($dialect, $dialect === Dialect::PostgreSql ? 'numeric' : 'bigint'), $nullable, $value->nullExtendedBy), $source);
    }

    /**
     * Identifies a field extraction operation.
     */
    #[Override]
    protected function operation(): ExpressionKind
    {
        return ExpressionKind::Extract;
    }

    /**
     * @return list<Expression> The temporal input, without a runtime value
     */
    #[Override]
    public function inputs(): array
    {
        return [$this->value];
    }

    /**
     * Returns the fixed operation name.
     */
    #[Override]
    public function spelling(): string
    {
        return 'EXTRACT';
    }

    /**
     * Keeps the facts derived from the operation's required operands.
     * @visibility SqlSemantics
     * @throws InvalidStructure
     */
    #[Override]
    public function withFacts(ExpressionFacts $facts): static
    {
        if ($facts != $this->facts) {
            throw new InvalidStructure('Extraction facts are derived from its field and input.');
        }
        return new static($this->source, $this->field, $this->value);
    }
}
''')
write('src/Binding/Scalar/Intrinsic/ExtractionField.php',header+r'''namespace SqlSemantics\Binding\Scalar\Intrinsic;

use SqlSemantics\Model\Scalar\Temporal\PostgreSqlField;

/**
 * Resolves PostgreSQL's datetime unit aliases to one semantic field.
 * @visibility SqlSemantics
 */
final class ExtractionField
{
    /**
     * Normalizes server datetime-unit spellings, including the ten-byte lookup key.
     */
    public static function postgres(string $name): ?PostgreSqlField
    {
        $name = strtoupper($name);
        $canonical = match (substr($name, 0, 10)) {
            'C', 'CENT', 'CENTURIES' => 'CENTURY',
            'D', 'DAYS' => 'DAY',
            'DEC', 'DECADES', 'DECS' => 'DECADE',
            'H', 'HOURS', 'HR', 'HRS' => 'HOUR',
            'J', 'JD' => 'JULIAN',
            'M', 'MIN', 'MINS', 'MINUTES' => 'MINUTE',
            'MICROSECON', 'US', 'USEC', 'USECS', 'USECOND', 'USECONDS' => 'MICROSECONDS',
            'MIL', 'MILLENNIA', 'MILS' => 'MILLENNIUM',
            'MILLISECON', 'MS', 'MSEC', 'MSECS', 'MSECOND', 'MSECONDS' => 'MILLISECONDS',
            'MON', 'MONS', 'MONTHS' => 'MONTH',
            'QTR' => 'QUARTER',
            'S', 'SEC', 'SECS', 'SECONDS' => 'SECOND',
            'TIMEZONE_H' => 'TIMEZONE_HOUR',
            'TIMEZONE_M' => 'TIMEZONE_MINUTE',
            'W', 'WEEKS' => 'WEEK',
            'Y', 'YR', 'YRS', 'YEARS' => 'YEAR',
            default => $name,
        };
        return PostgreSqlField::tryFrom($canonical);
    }
}
''')
write('src/Binding/Scalar/Intrinsic/ExtractBinder.php',header+r'''namespace SqlSemantics\Binding\Scalar\Intrinsic;

use SqlParser\Lexer\Token;
use SqlParser\Parser\Node;
use SqlSemantics\Ast\Definition\OptionReader;
use SqlSemantics\Ast\Tree;
use SqlSemantics\Binding\ExpressionBinder;
use SqlSemantics\Binding\Scope;
use SqlSemantics\Dialect;
use SqlSemantics\InvalidSql;
use SqlSemantics\Model\Scalar\Temporal\Extract;
use SqlSemantics\Model\Scalar\Temporal\MySqlUnit;
use SqlSemantics\Model\Validation\InputViolation;

/**
 * Binds EXTRACT's unit separately from its temporal operand.
 * @visibility SqlSemantics
 */
final class ExtractBinder
{
    /**
     * Recognizes the language operation without intercepting a quoted function name.
     * @throws InvalidSql
     */
    public static function bind(Node $source, Scope $scope): ?Extract
    {
        $first = $source->children[0] ?? null;
        if (!$first instanceof Token || !in_array($source->name, ['func_expr_common_subexpr', 'function_call_nonkeyword'], true) || strtoupper($first->text) !== 'EXTRACT') {
            return null;
        }
        $fieldNode = Tree::outer($source, ['extract_arg', 'interval'])[0] ?? null;
        $valueNode = Tree::outer($source, ['a_expr', 'expr'])[0] ?? null;
        if ($fieldNode === null || $valueNode === null) {
            throw new InvalidSql(InputViolation::FunctionArity, $source);
        }
        $token = $fieldNode->tokens()[0];
        $name = OptionReader::value($token, $scope->identifiers);
        $field = $scope->identifiers->dialect === Dialect::PostgreSql ? ExtractionField::postgres($name) : MySqlUnit::tryFrom(strtoupper($name));
        if ($field === null) {
            throw new InvalidSql(InputViolation::ExtractionField, $fieldNode);
        }
        return new Extract($source, $field, (new ExpressionBinder())->bind($valueNode, $scope));
    }
}
''')
