put('src/Binding/Configuration/Role/AccountNames.php',r'''namespace SqlSemantics\Binding\Configuration\Role;

use SqlParser\Lexer\Token;
use SqlParser\Parser\Node;
use SqlSemantics\Ast\Identifiers;
use SqlSemantics\Ast\Tree;
use SqlSemantics\Model\Configuration\Role\AccountName;
use SqlSemantics\Model\Validation\Collections;

/**
 * Reads lexical account names without treating names or host qualifiers as value expressions.
 * @visibility SqlSemantics
 */
final class AccountNames
{
    /**
     * @return non-empty-list<AccountName>
     */
    public static function read(Node $list, Identifiers $identifiers): array
    {
        $roles = [];
        foreach (Tree::outer($list, ['role']) as $role) {
            $tokens = $role->tokens();
            $roles[] = new AccountName(self::part($tokens[0], $identifiers), isset($tokens[2]) ? self::part($tokens[2], $identifiers) : null);
        }
        return Collections::nonEmpty($roles);
    }

    /**
     * Decodes MySQL string quoting when a name uses a string token, preserving identifier case.
     */
    public static function part(Token $token, Identifiers $identifiers): string
    {
        if ($token->name !== 'TEXT_STRING') {
            return $identifiers->name($token);
        }
        $text = $token->text;
        $quote = $text[0];
        $name = '';
        for ($i = 1; $i < strlen($text) - 1; ++$i) {
            $character = $text[$i];
            if ($character === '\\') {
                $character = $text[++$i];
                $name .= match ($character) {
                    '0' => "\0", 'n' => "\n", 'r' => "\r", 'b' => "\x08", 't' => "\t", 'Z' => "\x1a", '%', '_' => '\\' . $character, default => $character,
                };
            } else {
                $name .= $character;
                if ($character === $quote && ($text[$i + 1] ?? '') === $quote) {
                    ++$i;
                }
            }
        }
        return $name;
    }
}
''')
put('src/Binding/Configuration/Role/RoleBinder.php',r'''namespace SqlSemantics\Binding\Configuration\Role;

use SqlParser\Parser\Node;
use SqlSemantics\Ast\Identifiers;
use SqlSemantics\Ast\Tree;
use SqlSemantics\Dialect;
use SqlSemantics\Model\BoundStatement;
use SqlSemantics\Model\Configuration\Role\DefaultRolePolicy;
use SqlSemantics\Model\Configuration\Role\SessionRolePolicy;
use SqlSemantics\Model\Statement\Configuration\Role as Statement;
use SqlSemantics\Model\Statement\Origin;

/**
 * Separates session role selection from account default-role changes and variable assignment.
 * @visibility SqlSemantics
 */
final class RoleBinder
{
    /**
     * Recognizes the complete MySQL SET ROLE grammar, including default-role recipients.
     */
    public static function bind(Origin $origin, Node $node, Identifiers $identifiers): ?BoundStatement
    {
        if ($origin->dialect !== Dialect::MySql || $node->name !== 'set_role_stmt') {
            return null;
        }
        $words = array_map(static fn ($token): string => strtoupper($token->text), $node->tokens());
        $lists = Tree::outer($node, ['role_list']);
        if (($words[1] ?? '') === 'DEFAULT') {
            $accounts = AccountNames::read($lists[count($lists) - 1], $identifiers);
            return count($lists) === 2
                ? new Statement\SetDefaultRolesStatement($origin, AccountNames::read($lists[0], $identifiers), $accounts)
                : new Statement\SetDefaultRolePolicyStatement($origin, DefaultRolePolicy::from($words[3]), $accounts);
        }
        if ($lists === []) {
            return new Statement\SetRolePolicyStatement($origin, SessionRolePolicy::from($words[2]));
        }
        $roles = AccountNames::read($lists[0], $identifiers);
        return ($words[2] ?? '') === 'ALL'
            ? new Statement\SetRolesExceptStatement($origin, $roles)
            : new Statement\SetExplicitRolesStatement($origin, $roles);
    }
}
''')
put('src/Serialization/Session/Roles.php',r'''namespace SqlSemantics\Serialization\Session;

use SqlSemantics\Dialect;
use SqlSemantics\Model\Configuration\Role\AccountName;
use SqlSemantics\Model\Sql\Atom;
use SqlSemantics\Model\Sql\Build;
use SqlSemantics\Model\Sql\Literal;
use SqlSemantics\Model\Sql\Tree;
use SqlSemantics\Model\Statement\Configuration\Role as Statement;

/**
 * Writes role selection with required name boundaries, recipients, and policies.
 * @visibility SqlSemantics
 */
final class Roles
{
    /**
     * Writes session activation or account defaults according to the concrete operation.
     */
    public static function write(Statement\SetRolePolicyStatement|Statement\SetExplicitRolesStatement|Statement\SetRolesExceptStatement|Statement\SetDefaultRolePolicyStatement|Statement\SetDefaultRolesStatement $statement): Tree
    {
        if ($statement instanceof Statement\SetDefaultRolePolicyStatement || $statement instanceof Statement\SetDefaultRolesStatement) {
            $selection = $statement instanceof Statement\SetDefaultRolePolicyStatement ? Build::keyword($statement->policy->value) : self::accounts($statement->roles);
            return new Tree('default-roles', [Build::keyword('SET DEFAULT ROLE'), $selection, Build::keyword('TO'), self::accounts($statement->accounts)]);
        }
        $selection = match (true) {
            $statement instanceof Statement\SetRolePolicyStatement => Build::keyword($statement->policy->value),
            $statement instanceof Statement\SetExplicitRolesStatement => self::accounts($statement->roles),
            $statement instanceof Statement\SetRolesExceptStatement => new Tree('role-exclusions', [Build::keyword('ALL EXCEPT'), self::accounts($statement->excludedRoles)]),
        };
        return new Tree('session-roles', [Build::keyword('SET ROLE'), $selection]);
    }

    /**
     * @param non-empty-list<AccountName> $accounts
     */
    public static function accounts(array $accounts): Tree
    {
        return Build::separated(array_map(static fn (AccountName $name): Tree => new Tree('account-name', [
            new Atom('literal', Literal::encode($name->username, Dialect::MySql)[0]),
            ...($name->host === null ? [] : [new Atom('punctuation', '@'), new Atom('literal', Literal::encode($name->host, Dialect::MySql)[0])]),
        ]), $accounts));
    }
}
