put('src/Model/Scalar/Temporal/IntervalFields.php',r'''namespace SqlSemantics\Model\Scalar\Temporal;

/**
 * Describes the calendar and clock fields that a MySQL interval unit contains.
 * @visibility SqlSemantics
 */
final class IntervalFields
{
    /**
     * Identifies intervals without a clock field.
     */
    public static function calendarOnly(MySqlUnit $unit): bool
    {
        return in_array($unit, [MySqlUnit::Year, MySqlUnit::Quarter, MySqlUnit::Month, MySqlUnit::Week, MySqlUnit::Day, MySqlUnit::YearMonth], true);
    }

    /**
     * Identifies intervals without a calendar field.
     */
    public static function clockOnly(MySqlUnit $unit): bool
    {
        return in_array($unit, [MySqlUnit::Hour, MySqlUnit::Minute, MySqlUnit::Second, MySqlUnit::Microsecond, MySqlUnit::HourMinute, MySqlUnit::HourSecond, MySqlUnit::HourMicrosecond, MySqlUnit::MinuteSecond, MySqlUnit::MinuteMicrosecond, MySqlUnit::SecondMicrosecond], true);
    }

    /**
     * Returns the default parameter family required by the interval's lexical representation.
     */
    public static function quantityType(MySqlUnit $unit): string
    {
        return match ($unit) {
            MySqlUnit::Year, MySqlUnit::Quarter, MySqlUnit::Month, MySqlUnit::Week, MySqlUnit::Day, MySqlUnit::Hour, MySqlUnit::Minute, MySqlUnit::Microsecond => 'bigint',
            MySqlUnit::Second => 'numeric',
            default => 'varchar',
        };
    }
}
''')
put('src/Model/Scalar/Temporal/DateArithmeticFacts.php',r'''namespace SqlSemantics\Model\Scalar\Temporal;

use SqlSemantics\Dialect;
use SqlSemantics\Model\Expression;
use SqlSemantics\Model\Scalar\ExpressionFacts;
use SqlSemantics\Model\Scalar\Reference\Parameter;
use SqlSemantics\Model\Scalar\Value\Literal;
use SqlSemantics\Type\Identity\BuiltinIdentity;
use SqlSemantics\Type\Nullability;
use SqlSemantics\Type\TypeDescriptor;

/**
 * Resolves temporal result families and inferred parameters without evaluating operands.
 * @visibility SqlSemantics
 */
final class DateArithmeticFacts
{
    /**
     * Supplies a missing dynamic parameter type when the selected release infers one.
     */
    public static function parameter(Expression $input, string $type, DateArithmeticRules $rules): Expression
    {
        if ($rules !== DateArithmeticRules::Current || !$input instanceof Parameter || $input->type->identity !== BuiltinIdentity::Unknown) {
            return $input;
        }
        return $input->withFacts(new ExpressionFacts(TypeDescriptor::builtin(Dialect::MySql, $type), $input->nullability, $input->nullExtendedBy));
    }

    /**
     * Derives the SQL result family from declarations and interval fields.
     */
    public static function result(Expression $value, MySqlUnit $unit, DateArithmeticRules $rules): TypeDescriptor
    {
        $name = $value->type->name;
        $result = match ($name) {
            'datetime', 'timestamp' => 'datetime',
            'date' => IntervalFields::calendarOnly($unit) ? 'date' : 'datetime',
            'time' => $rules === DateArithmeticRules::Legacy || IntervalFields::clockOnly($unit) ? 'time' : 'datetime',
            'unknown' => $value instanceof Literal || $value instanceof Parameter ? 'varchar' : 'unknown',
            default => 'varchar',
        };
        return TypeDescriptor::builtin(Dialect::MySql, $result);
    }

    /**
     * Invalid or out-of-range temporal arithmetic may return NULL even for non-NULL inputs.
     */
    public static function nullability(Expression $value, Expression $quantity): Nullability
    {
        return $value->nullability === Nullability::AlwaysNull || $quantity->nullability === Nullability::AlwaysNull ? Nullability::AlwaysNull : Nullability::MaybeNull;
    }
}
''')
put('src/Model/Scalar/Temporal/DateShift.php',r'''namespace SqlSemantics\Model\Scalar\Temporal;

use Override;
use SqlParser\Lexer\Token;
use SqlParser\Parser\Node;
use SqlSemantics\Dialect;
use SqlSemantics\Model\Expression;
use SqlSemantics\Model\ExpressionKind;
use SqlSemantics\Model\Scalar\ExpressionFacts;
use SqlSemantics\Model\Validation\InvalidStructure;
use SqlSemantics\Model\Validation\QueryComparison;

/**
 * Applies a classified MySQL interval to a required temporal input without evaluating either.
 * @visibility public
 * @example Inspecting temporal arithmetic
 *     $query = (new \SqlSemantics\Binder((new \SqlSemantics\SchemaBuilder(\SqlSemantics\Dialect::MySql))->build()))->bind('SELECT CURRENT_DATE + INTERVAL 2 DAY');
 *     $query->outputs[0]->expression->unit->value // => 'DAY'
 */
final class DateShift extends Expression
{
    /**
     * The date or time input, including an inferred parameter type when applicable.
     */
    public readonly Expression $value;
    /**
     * The interval quantity, whose unit determines how the consumer interprets it.
     */
    public readonly Expression $quantity;

    /**
     * Derives the result from required scalar operands and the selected release's arithmetic rules.
     * @throws InvalidStructure
     */
    public function __construct(Node|Token $source, Expression $value, Expression $quantity, public readonly MySqlUnit $unit, public readonly ShiftDirection $direction, public readonly DateArithmeticRules $rules)
    {
        if ($value->type->dialect !== Dialect::MySql || $quantity->type->dialect !== Dialect::MySql) {
            throw new InvalidStructure('MySQL interval arithmetic requires MySQL operands.');
        }
        if (in_array(false, [in_array(QueryComparison::width($value), [null, 1], true), in_array(QueryComparison::width($quantity), [null, 1], true)], true)) {
            throw new InvalidStructure('Temporal arithmetic requires scalar operands.');
        }
        $this->value = DateArithmeticFacts::parameter($value, IntervalFields::calendarOnly($unit) ? 'date' : 'datetime', $rules);
        $this->quantity = DateArithmeticFacts::parameter($quantity, IntervalFields::quantityType($unit), $rules);
        $extensions = array_values(array_unique([...$value->nullExtendedBy, ...$quantity->nullExtendedBy]));
        parent::__construct(new ExpressionFacts(DateArithmeticFacts::result($this->value, $unit, $rules), DateArithmeticFacts::nullability($this->value, $this->quantity), $extensions), $source);
    }

    #[Override]
    protected function operation(): ExpressionKind
    {
        return ExpressionKind::DateShift;
    }

    /**
     * @return list<Expression> The temporal input followed by its interval quantity
     */
    #[Override]
    public function inputs(): array
    {
        return [$this->value, $this->quantity];
    }

    /**
     * Returns the canonical operation for this shift direction.
     */
    #[Override]
    public function spelling(): string
    {
        return $this->direction->value;
    }

    /**
     * Preserves the result facts derived from temporal operands and interval fields.
     * @visibility SqlSemantics
     * @throws InvalidStructure
     */
    #[Override]
    public function withFacts(ExpressionFacts $facts): static
    {
        if ($facts !== $this->facts) {
            throw new InvalidStructure('Temporal arithmetic facts are derived from its operands and release rules.');
        }
        return new self($this->source, $this->value, $this->quantity, $this->unit, $this->direction, $this->rules);
    }
}
''')
put('src/Binding/Scalar/Intrinsic/DateShiftBinder.php',r'''namespace SqlSemantics\Binding\Scalar\Intrinsic;

use SqlParser\Lexer\Token;
use SqlParser\Parser\Node;
use SqlSemantics\Ast\Tree;
use SqlSemantics\Binding\ExpressionBinder;
use SqlSemantics\Binding\Scope;
use SqlSemantics\Dialect;
use SqlSemantics\InvalidSql;
use SqlSemantics\Model\Scalar\Temporal\DateArithmeticRules;
use SqlSemantics\Model\Scalar\Temporal\DateShift;
use SqlSemantics\Model\Scalar\Temporal\MySqlUnit;
use SqlSemantics\Model\Scalar\Temporal\ShiftDirection;
use SqlSemantics\Model\Validation\InputViolation;
use SqlSemantics\Model\Validation\QueryComparison;

/**
 * Classifies infix intervals and DATE_ADD/DATE_SUB forms before generic operator or function binding.
 * @visibility SqlSemantics
 */
final class DateShiftBinder
{
    /**
     * Keeps the temporal input, interval quantity, unit, and direction in separate roles.
     * @throws InvalidSql
     */
    public static function bind(Node $source, Scope $scope): ?DateShift
    {
        if ($scope->identifiers->dialect !== Dialect::MySql || !in_array($source->name, ['bit_expr', 'simple_expr', 'function_call_nonkeyword'], true)) {
            return null;
        }
        $first = $source->children[0] ?? null;
        $name = $first instanceof Token ? strtoupper($first->text) : '';
        $call = $source->name === 'function_call_nonkeyword' && in_array($name, ['ADDDATE', 'SUBDATE', 'DATE_ADD', 'DATE_SUB'], true);
        $interval = Tree::child($source, ['interval']);
        if (!$call && $interval === null) {
            return null;
        }
        $operands = array_values(array_filter($source->children, static fn ($child): bool => $child instanceof Node && in_array($child->name, ['expr', 'bit_expr'], true)));
        if (count($operands) !== 2) {
            throw new InvalidSql(InputViolation::TemporalOperand, $source);
        }
        if ($name === 'INTERVAL') {
            $operands = array_reverse($operands);
        }
        $value = (new ExpressionBinder())->bind($operands[0], $scope);
        $quantity = (new ExpressionBinder())->bind($operands[1], $scope);
        if (!in_array(QueryComparison::width($value), [null, 1], true) || !in_array(QueryComparison::width($quantity), [null, 1], true)) {
            throw new InvalidSql(InputViolation::TemporalOperand, $source);
        }
        $tokens = array_map(static fn (Token $token): string => strtoupper($token->text), array_values(array_filter($source->children, static fn ($child): bool => $child instanceof Token)));
        $direction = in_array('-', $tokens, true) || in_array($name, ['DATE_SUB', 'SUBDATE'], true) ? ShiftDirection::Subtract : ShiftDirection::Add;
        $unit = $interval === null ? MySqlUnit::Day : MySqlUnit::from(strtoupper(Tree::text($interval)));
        $version = $scope->queries?->tables->schema->grammarVersion ?? '';
        $rules = str_starts_with($version, 'mysql-5.') ? DateArithmeticRules::Legacy : DateArithmeticRules::Current;
        return new DateShift($source, $value, $quantity, $unit, $direction, $rules);
    }
