<?php

declare(strict_types=1);

namespace SqlSemantics\Binding\Configuration;

use SqlParser\Parser\Node;
use SqlSemantics\Ast\Tree;
use SqlSemantics\Binding\LiteralBinder;
use SqlSemantics\Binding\Statement\UnclassifiedSql;
use SqlSemantics\Dialect;
use SqlSemantics\Model\Scalar\Value\Literal;
use SqlSemantics\Model\Statement\Configuration\Transaction as Statement;
use SqlSemantics\Model\Statement\ConfigurationStatement;
use SqlSemantics\Model\Statement\Origin;
use SqlSemantics\Model\Transaction\Access;
use SqlSemantics\Model\Transaction\Configuration\DefaultScope;
use SqlSemantics\Model\Transaction\Configuration\Deferrability;
use SqlSemantics\Model\Transaction\Configuration\Locality;
use SqlSemantics\Model\Transaction\Isolation;
use SqlSemantics\Model\Validation\Collections;

/**
 * Binds transaction policy requests at their grammar boundaries, separate from variable assignments.
 * @visibility SqlSemantics
 */
final class TransactionSettings
{
    /**
     * Separates current, next, default, and imported-snapshot operations without applying them.
     * @throws UnclassifiedSql
     */
    public static function bind(Origin $origin, Node $source): ?ConfigurationStatement
    {
        if ($origin->dialect === Dialect::MySql && $source->name === 'set') {
            return self::mysql($origin, $source);
        }
        if ($origin->dialect !== Dialect::PostgreSql || $source->name !== 'VariableSetStmt') {
            return null;
        }
        $rest = Tree::child($source, ['set_rest']);
        if ($rest === null) {
            return null;
        }
        $locality = ($source->tokens()[1]->name ?? '') === 'LOCAL' ? Locality::Local : Locality::Session;
        $list = Tree::child($rest, ['transaction_mode_list']);
        if ($list === null) {
            return self::snapshot($origin, $rest, $locality);
        }
        $modes = [];
        foreach (Tree::outer($list, ['transaction_mode_item']) as $item) {
            $isolation = Tree::child($item, ['iso_level']);
            $text = strtoupper(Tree::text($item));
            $modes[] = $isolation !== null ? Isolation::from(strtoupper(Tree::text($isolation))) : (Access::tryFrom($text) ?? Deferrability::from($text));
        }
        return ($rest->tokens()[0]->name ?? '') === 'SESSION'
            ? new Statement\SetSessionTransactionStatement($origin, Collections::nonEmpty($modes), $locality)
            : new Statement\SetCurrentTransactionStatement($origin, Collections::nonEmpty($modes), $locality);
    }

    /**
     * Reads the MySQL one-shot or explicitly scoped configuration form.
     */
    private static function mysql(Origin $origin, Node $source): ?ConfigurationStatement
    {
        $characteristics = Tree::outer($source, ['transaction_characteristics'])[0] ?? null;
        if ($characteristics === null) {
            return null;
        }
        $isolation = Tree::child($characteristics, ['isolation_level']);
        $access = Tree::child($characteristics, ['transaction_access_mode']);
        $isolation = $isolation === null ? null : Isolation::from(implode(' ', array_slice(SettingTokens::words($isolation->tokens()), 2)));
        $access = $access === null ? null : Access::from(strtoupper(Tree::text($access)));
        $scope = Tree::outer($source, ['option_type'])[0] ?? null;
        if ($scope === null) {
            return new Statement\SetNextTransactionStatement($origin, $isolation, $access);
        }
        $scope = strtoupper(Tree::text($scope));
        return new Statement\SetDefaultTransactionStatement($origin, $scope === 'LOCAL' ? DefaultScope::Session : DefaultScope::from($scope), $isolation, $access);
    }

    /**
     * Reads only the explicit PostgreSQL snapshot-import production, retaining the identifier literal.
     * @throws UnclassifiedSql
     */
    private static function snapshot(Origin $origin, Node $rest, Locality $locality): ?Statement\SetTransactionSnapshotStatement
    {
        $more = Tree::child($rest, ['set_rest_more']);
        if ($more === null || array_slice(SettingTokens::words($more->tokens()), 0, 2) !== ['TRANSACTION', 'SNAPSHOT']) {
            return null;
        }
        $value = Tree::child($more, ['Sconst']);
        $literal = $value === null ? null : (new LiteralBinder(Dialect::PostgreSql))->bind($value->tokens()[0]);
        if (!$literal instanceof Literal) {
            throw new UnclassifiedSql('A transaction snapshot request requires its identifier literal.');
        }
        return new Statement\SetTransactionSnapshotStatement($origin, $literal, $locality);
    }
}
