write('src/Model/Statement/Definition/PostgreSql/ImportForeignSchemaStatement.php',r'''namespace SqlSemantics\Model\Statement\Definition\PostgreSql;

use Override;
use SqlSemantics\Dialect;
use SqlSemantics\Model\BoundStatement;
use SqlSemantics\Model\Definition\Foreign\AllForeignTables;
use SqlSemantics\Model\Definition\Foreign\ExcludeForeignTables;
use SqlSemantics\Model\Definition\Foreign\ForeignOption;
use SqlSemantics\Model\Definition\Foreign\ImportOnlyTables;
use SqlSemantics\Model\Statement\Origin;
use SqlSemantics\Model\Statement\StatementKind;
use SqlSemantics\Model\Validation\Collections;
use SqlSemantics\Model\Validation\InvalidStructure;

/**
 * Imports selected remote definitions into one local schema without contacting a server.
 * @visibility public
 * @example Inspecting the destination and selection
 *     $statement = (new \SqlSemantics\Binder((new \SqlSemantics\SchemaBuilder(\SqlSemantics\Dialect::PostgreSql))->build()))->bind('IMPORT FOREIGN SCHEMA ext LIMIT TO (users) FROM SERVER remote INTO app');
 *     $statement->localSchema // => 'app'
 *     $statement->selection instanceof \SqlSemantics\Model\Definition\Foreign\ImportOnlyTables // => true
 */
final class ImportForeignSchemaStatement extends BoundStatement
{
    /**
     * @param list<ForeignOption> $options Ordered wrapper-specific text options
     * @throws InvalidStructure
     */
    public function __construct(
        Origin $origin,
        public readonly string $remoteSchema,
        public readonly string $server,
        public readonly string $localSchema,
        public readonly AllForeignTables|ImportOnlyTables|ExcludeForeignTables $selection = AllForeignTables::InSchema,
        public readonly array $options = [],
    ) {
        if ($origin->dialect !== Dialect::PostgreSql || $remoteSchema === '' || $server === '' || $localSchema === '') {
            throw new InvalidStructure('Foreign schema import requires PostgreSQL and nonempty remote, server, and local names.');
        }
        Collections::objects($options, ForeignOption::class);
        parent::__construct($origin);
    }

    #[Override]
    protected function operation(): StatementKind
    {
        return StatementKind::Import;
    }

    /**
     * Retains all import operands while replacing diagnostic provenance.
     */
    #[Override]
    public function withOrigin(Origin $origin): static
    {
        return new self($origin, $this->remoteSchema, $this->server, $this->localSchema, $this->selection, $this->options);
    }

    /**
     * Replaces the remote schema and the server that interprets it together.
     */
    public function withRemote(string $server, string $remoteSchema): self
    {
        return $this->changed(new self($this->origin, $remoteSchema, $server, $this->localSchema, $this->selection, $this->options));
    }

    /**
     * Selects the local schema that will receive the imported declarations.
     */
    public function withLocalSchema(string $localSchema): self
    {
        return $this->changed(new self($this->origin, $this->remoteSchema, $this->server, $localSchema, $this->selection, $this->options));
    }

    /**
     * Changes the complete selection while preserving its required table list.
     */
    public function withSelection(AllForeignTables|ImportOnlyTables|ExcludeForeignTables $selection): self
    {
        return $this->changed(new self($this->origin, $this->remoteSchema, $this->server, $this->localSchema, $selection, $this->options));
    }

    /**
     * @param list<ForeignOption> $options Ordered wrapper-specific options
     */
    public function withOptions(array $options): self
    {
        return $this->changed(new self($this->origin, $this->remoteSchema, $this->server, $this->localSchema, $this->selection, $options));
    }
}
''')
write('src/Binding/Statement/Definition/ForeignImports.php',r'''namespace SqlSemantics\Binding\Statement\Definition;

use SqlParser\Parser\Node;
use SqlSemantics\Ast\Tree;
use SqlSemantics\Binding\Query\QueryContext;
use SqlSemantics\Binding\Statement\UnclassifiedSql;
use SqlSemantics\Dialect;
use SqlSemantics\Model\Definition\Foreign\AllForeignTables;
use SqlSemantics\Model\Definition\Foreign\ExcludeForeignTables;
use SqlSemantics\Model\Definition\Foreign\ImportOnlyTables;
use SqlSemantics\Model\Statement\Definition\PostgreSql\ImportForeignSchemaStatement;
use SqlSemantics\Model\Statement\Origin;

/**
 * Separates import endpoints, remote relation selection, and wrapper options.
 * @visibility SqlSemantics
 */
final class ForeignImports
{
    /**
     * Binds remote identifiers without incorrectly resolving them as local tables.
     * @throws UnclassifiedSql
     */
    public static function bind(Origin $origin, Node $source, QueryContext $context): ?ImportForeignSchemaStatement
    {
        if ($origin->dialect !== Dialect::PostgreSql || $source->name !== 'ImportForeignSchemaStmt') {
            return null;
        }
        $names = Tree::outer($source, ['name']);
        if (count($names) !== 3) {
            throw new UnclassifiedSql('A foreign schema import requires remote schema, server, and local schema names.');
        }
        $identifiers = $context->tables->identifiers;
        $qualification = Tree::child($source, ['import_qualification']);
        $tables = $qualification === null ? [] : array_map(static fn (Node $node) => ForeignOperands::relation($node, $identifiers), Tree::outer($qualification, ['relation_expr']));
        $selection = $qualification === null ? AllForeignTables::InSchema : (strtoupper($qualification->tokens()[0]->text) === 'LIMIT' ? new ImportOnlyTables($tables) : new ExcludeForeignTables($tables));
        $options = array_map(static fn (Node $node) => ForeignOperands::option($node, $identifiers), Tree::outer($source, ['generic_option_elem']));
        return new ImportForeignSchemaStatement($origin, $identifiers->name($names[0]->tokens()[0]), $identifiers->name($names[1]->tokens()[0]), $identifiers->name($names[2]->tokens()[0]), $selection, $options);
    }
}
''')
write('src/Binding/Statement/Definition/ForeignOperands.php',r'''namespace SqlSemantics\Binding\Statement\Definition;

use SqlParser\Parser\Node;
use SqlSemantics\Ast\Identifiers;
use SqlSemantics\Ast\Tree;
use SqlSemantics\Binding\LiteralBinder;
use SqlSemantics\Binding\Statement\UnclassifiedSql;
use SqlSemantics\Dialect;
use SqlSemantics\InvalidSql;
use SqlSemantics\Model\Definition\Foreign\ForeignOption;
use SqlSemantics\Model\Definition\Foreign\ForeignRelation;
use SqlSemantics\Model\Relation\QualifiedName;
use SqlSemantics\Model\Scalar\Value\Literal;
use SqlSemantics\Model\Validation\InputViolation;

/**
 * Reads remote relation selectors and literal-valued foreign-data wrapper options.
 * @visibility SqlSemantics
 */
final class ForeignOperands
{
    /**
     * Keeps qualification and descendant scope for the foreign-data wrapper.
     * @throws UnclassifiedSql
     * @throws InvalidSql
     */
    public static function relation(Node $source, Identifiers $identifiers): ForeignRelation
    {
        $name = Tree::outer($source, ['qualified_name'])[0] ?? throw new UnclassifiedSql('A foreign relation selector requires its name.');
        foreach (Tree::outer($name, ['indirection_el']) as $part) {
            if (Tree::child($part, ['attr_name']) === null) {
                throw new InvalidSql(InputViolation::RelationName, $name);
            }
        }
        $parts = $identifiers->parts($name);
        if (count($parts) > 3 || in_array('', $parts, true)) {
            throw new InvalidSql(InputViolation::RelationName, $name);
        }
        return new ForeignRelation(new QualifiedName($parts), strtoupper($source->tokens()[0]->text) !== 'ONLY');
    }

    /**
     * Requires a text literal rather than accepting arbitrary option expressions.
     * @throws UnclassifiedSql
     */
    public static function option(Node $source, Identifiers $identifiers): ForeignOption
    {
        $name = Tree::child($source, ['generic_option_name']) ?? throw new UnclassifiedSql('A foreign option requires its name.');
        $argument = Tree::child($source, ['generic_option_arg']) ?? throw new UnclassifiedSql('A foreign option requires its text operand.');
        $value = (new LiteralBinder(Dialect::PostgreSql))->bind($argument->tokens()[0]);
        if (!$value instanceof Literal) {
            throw new UnclassifiedSql('A foreign option requires a text literal.');
        }
        return new ForeignOption($identifiers->name($name->tokens()[0]), $value);
    }
}
''')
write('src/Serialization/Definition/ForeignImports.php',r'''namespace SqlSemantics\Serialization\Definition;

use SqlSemantics\Dialect;
use SqlSemantics\Model\BoundStatement;
use SqlSemantics\Model\Definition\Foreign\AllForeignTables;
use SqlSemantics\Model\Definition\Foreign\ForeignOption;
use SqlSemantics\Model\Definition\Foreign\ForeignRelation;
use SqlSemantics\Model\Definition\Foreign\ImportOnlyTables;
use SqlSemantics\Model\Sql\Build;
use SqlSemantics\Model\Sql\Tree;
use SqlSemantics\Model\Statement\Definition\PostgreSql\ImportForeignSchemaStatement;
use SqlSemantics\Serialization\Expressions;

/**
 * Writes import endpoints and the closed set of remote selection forms.
 * @visibility SqlSemantics
 */
final class ForeignImports
{
    /**
     * Returns null for operations outside the foreign schema import family.
     */
    public static function write(BoundStatement $statement): ?Tree
    {
        if (!$statement instanceof ImportForeignSchemaStatement) {
            return null;
        }
        $selection = $statement->selection;
        $filter = $selection instanceof AllForeignTables ? [] : [Build::keyword($selection instanceof ImportOnlyTables ? 'LIMIT TO' : 'EXCEPT'), Build::parentheses(Build::separated(array_map(static fn (ForeignRelation $relation): Tree => new Tree('remote-relation', [...($relation->includeDescendants ? [] : [Build::keyword('ONLY')]), Build::identifier($relation->name->parts, Dialect::PostgreSql)]), $selection->tables)))];
        $options = $statement->options === [] ? [] : [Build::keyword('OPTIONS'), Build::parentheses(Build::separated(array_map(static fn (ForeignOption $option): Tree => new Tree('foreign-option', [Build::identifier([$option->name], Dialect::PostgreSql), Expressions::write($option->value)]), $statement->options)))];
        return new Tree('import-foreign-schema', [
            Build::keyword('IMPORT FOREIGN SCHEMA'), Build::identifier([$statement->remoteSchema], Dialect::PostgreSql), ...$filter,
            Build::keyword('FROM SERVER'), Build::identifier([$statement->server], Dialect::PostgreSql),
            Build::keyword('INTO'), Build::identifier([$statement->localSchema], Dialect::PostgreSql), ...$options,
        ]);
    }
}
''')
