put('src/Binding/Statement/Definition/Database/MySqlDatabases.php',r'''namespace SqlSemantics\Binding\Statement\Definition\Database;

use SqlParser\Parser\Node;
use SqlSemantics\Ast\Tree;
use SqlSemantics\Binding\Query\QueryContext;
use SqlSemantics\Binding\Statement\UnclassifiedSql;
use SqlSemantics\Dialect;
use SqlSemantics\Model\BoundStatement;
use SqlSemantics\Model\Definition\Database\CurrentDatabase;
use SqlSemantics\Model\Statement\Definition\MySql as Statement;
use SqlSemantics\Model\Statement\Origin;

/**
 * Binds database creation, default changes, and legacy directory-name upgrades separately.
 * @visibility SqlSemantics
 */
final class MySqlDatabases
{
    /**
     * Resolves an omitted database name from the supplied snapshot when available.
     * @throws UnclassifiedSql
     */
    public static function bind(Origin $origin, Node $source, QueryContext $context): ?BoundStatement
    {
        $tokens = $source->tokens();
        $operation = strtoupper($tokens[0]->text ?? '');
        if ($origin->dialect !== Dialect::MySql || !in_array($operation, ['CREATE', 'ALTER'], true) || ($tokens[1]->name ?? '') !== 'DATABASE') {
            return null;
        }
        $name = Tree::child($source, ['ident', 'ident_or_empty']);
        $target = $name === null ? ($context->tables->schema->defaultSchema === '' ? CurrentDatabase::Session : $context->tables->schema->defaultSchema) : $context->tables->identifiers->name($name->tokens()[0]);
        $upgrade = array_filter($source->children, static fn ($child): bool => $child instanceof \SqlParser\Lexer\Token && $child->name === 'UPGRADE_SYM') !== [];
        if ($upgrade) {
            return new Statement\UpgradeDatabaseDirectoryStatement($origin, is_string($target) ? $target : throw new UnclassifiedSql('A directory upgrade requires a named database.'));
        }
        if ($operation === 'CREATE') {
            return new Statement\CreateDatabaseStatement($origin, is_string($target) ? $target : throw new UnclassifiedSql('Database creation requires a named database.'), DatabaseOptions::creation($source, $context->tables->identifiers), Tree::child($source, ['opt_if_not_exists']) !== null);
        }
        return new Statement\AlterDatabaseStatement($origin, $target, DatabaseOptions::alteration($source, $context->tables->identifiers));
    }
}
''')
put('src/Binding/Statement/Definition/Database/DatabaseOptions.php',r'''namespace SqlSemantics\Binding\Statement\Definition\Database;

use SqlParser\Parser\Node;
use SqlSemantics\Ast\Identifiers;
use SqlSemantics\Ast\Tree;
use SqlSemantics\Binding\Statement\UnclassifiedSql;
use SqlSemantics\InvalidSql;
use SqlSemantics\Model\Definition\Database\DatabaseCharacterSet;
use SqlSemantics\Model\Definition\Database\DatabaseCollation;
use SqlSemantics\Model\Definition\Database\DatabaseEncryption;
use SqlSemantics\Model\Definition\Database\DatabaseReadOnly;
use SqlSemantics\Model\Definition\Database\ServerCharacterDefault;
use SqlSemantics\Model\Validation\Collections;
use SqlSemantics\Model\Validation\InputViolation;

/**
 * Reads explicitly classified database defaults and access requests in source order.
 * @visibility SqlSemantics
 */
final class DatabaseOptions
{
    /**
     * @return list<DatabaseCharacterSet|DatabaseCollation|DatabaseEncryption> Initial database defaults
     */
    public static function creation(Node $source, Identifiers $identifiers): array
    {
        return array_map(static fn (Node $option) => self::initial($option, $identifiers), Tree::outer($source, ['create_database_option']));
    }

    /**
     * @return non-empty-list<DatabaseCharacterSet|DatabaseCollation|DatabaseEncryption|DatabaseReadOnly> Changes to existing defaults
     * @throws InvalidSql
     */
    public static function alteration(Node $source, Identifiers $identifiers): array
    {
        $options = [];
        $readOnly = null;
        foreach (Tree::outer($source, ['create_database_option', 'ternary_option']) as $option) {
            if ($option->name !== 'ternary_option') {
                $options[] = self::initial($option, $identifiers);
                continue;
            }
            $access = OptionValues::readOnly($option);
            if ($readOnly !== null && $readOnly !== $access) {
                throw new InvalidSql(InputViolation::DatabaseReadOnly, $option);
            }
            $options[] = $readOnly = $access;
        }
        return Collections::nonEmpty($options);
    }

    /**
     * Reads only creation-legal option roles; READ ONLY has a separate alteration path.
     * @throws UnclassifiedSql
     * @throws InvalidSql
     */
    public static function initial(Node $option, Identifiers $identifiers): DatabaseCharacterSet|DatabaseCollation|DatabaseEncryption
    {
        $charset = Tree::child($option, ['default_charset']);
        $collation = Tree::child($option, ['default_collation']);
        if ($charset !== null || $collation !== null) {
            $part = $charset ?? $collation;
            $name = Tree::outer($part, ['charset_name_or_default', 'collation_name_or_default', 'charset_name', 'collation_name'])[0] ?? throw new UnclassifiedSql('A database character default requires its name.');
            $token = $name->tokens()[0];
            $value = in_array($token->name, ['DEFAULT', 'DEFAULT_SYM'], true) ? ServerCharacterDefault::Inherit : OptionValues::name($token, $identifiers);
            if ($value === '') {
                throw new InvalidSql(InputViolation::DatabaseCharacterName, $name);
            }
            return $charset !== null ? new DatabaseCharacterSet($value) : new DatabaseCollation($value);
        }
        $encryption = Tree::child($option, ['default_encryption']);
        if ($encryption !== null) {
            return OptionValues::encryption($encryption, $identifiers);
        }
        throw new UnclassifiedSql('Unclassified database default: ' . Tree::text($option));
    }
}
''')
put('src/Binding/Statement/Definition/Database/OptionValues.php',r'''namespace SqlSemantics\Binding\Statement\Definition\Database;

use SqlParser\Lexer\Token;
use SqlParser\Parser\Node;
use SqlSemantics\Ast\Identifiers;
use SqlSemantics\Ast\Tree;
use SqlSemantics\Binding\Statement\UnclassifiedSql;
use SqlSemantics\InvalidSql;
use SqlSemantics\Model\Definition\Database\DatabaseEncryption;
use SqlSemantics\Model\Definition\Database\DatabaseReadOnly;
use SqlSemantics\Model\Validation\InputViolation;

/**
 * Decodes the fixed operand domains used by database defaults without evaluating expressions.
 * @visibility SqlSemantics
 */
final class OptionValues
{
    /**
     * Interprets identifier-or-text names with MySQL's lexical string escaping.
     */
    public static function name(Token $token, Identifiers $identifiers): string
    {
        $name = $identifiers->name($token);
        if ($token->name !== 'TEXT_STRING') {
            return $name;
        }
        return preg_replace_callback('/\\\\(.)/s', static fn (array $match): string => match ($match[1]) {
            '0' => "\0", 'b' => "\x08", 'n' => "\n", 'r' => "\r", 't' => "\t", 'Z' => "\x1a", '%', '_' => $match[0], default => $match[1],
        }, $name) ?? $name;
    }

    /**
     * Maps DEFAULT and zero to the same writable database policy.
     * @throws InvalidSql
     */
    public static function readOnly(Node $source): DatabaseReadOnly
    {
        $text = strtoupper(Tree::text($source));
        if ($text === 'DEFAULT' || preg_match('/^0+$/D', $text) === 1 || preg_match('/^(?:0X0+|X\x270+\x27)$/D', $text) === 1) {
            return DatabaseReadOnly::Disabled;
        }
        if (preg_match('/^(?:0*1|0X0*1|X\x270*1\x27)$/D', $text) === 1) {
            return DatabaseReadOnly::Enabled;
        }
        throw new InvalidSql(InputViolation::DatabaseReadOnly, $source);
    }

    /**
     * Requires the encryption switches defined by the database language.
     * @throws UnclassifiedSql
     * @throws InvalidSql
     */
    public static function encryption(Node $source, Identifiers $identifiers): DatabaseEncryption
    {
        $literal = Tree::child($source, ['TEXT_STRING_sys']) ?? throw new UnclassifiedSql('Database encryption requires its literal option.');
        return match (strtoupper(self::name($literal->tokens()[0], $identifiers))) {
            'Y' => DatabaseEncryption::Enabled,
            'N' => DatabaseEncryption::Disabled,
            default => throw new InvalidSql(InputViolation::DatabaseEncryption, $source),
        };
    }
}
''')
put('src/Serialization/Definition/Database/MySqlDatabases.php',r'''namespace SqlSemantics\Serialization\Definition\Database;

use SqlSemantics\Dialect;
use SqlSemantics\Model\BoundStatement;
use SqlSemantics\Model\Definition\Database\DatabaseCharacterSet;
use SqlSemantics\Model\Definition\Database\DatabaseCollation;
use SqlSemantics\Model\Definition\Database\DatabaseEncryption;
use SqlSemantics\Model\Definition\Database\DatabaseReadOnly;
use SqlSemantics\Model\Definition\Database\ServerCharacterDefault;
use SqlSemantics\Model\Sql\Atom;
use SqlSemantics\Model\Sql\Build;
use SqlSemantics\Model\Sql\Tree;
use SqlSemantics\Model\Statement\Definition\MySql as Statement;

/**
 * Writes database requests from their explicit target and option domains.
 * @visibility SqlSemantics
 */
final class MySqlDatabases
{
    /**
     * Preserves default request order and separates upgrades from option changes.
     */
    public static function write(BoundStatement $statement): ?Tree
    {
        if ($statement instanceof Statement\UpgradeDatabaseDirectoryStatement) {
            return new Tree('database-directory-upgrade', [Build::keyword('ALTER DATABASE'), Build::identifier([$statement->name], Dialect::MySql), Build::keyword('UPGRADE DATA DIRECTORY NAME')]);
        }
        if (!$statement instanceof Statement\CreateDatabaseStatement && !$statement instanceof Statement\AlterDatabaseStatement) {
            return null;
        }
        return new Tree('database-defaults', [
            Build::keyword($statement instanceof Statement\CreateDatabaseStatement ? 'CREATE DATABASE' . ($statement->ifNotExists ? ' IF NOT EXISTS' : '') : 'ALTER DATABASE'),
            ...(is_string($statement->name) ? [Build::identifier([$statement->name], Dialect::MySql)] : []),
            ...array_map(self::option(...), $statement->options),
        ]);
    }

    /**
     * Writes each classified role with an identifier or fixed value rather than arbitrary SQL.
     */
    public static function option(DatabaseCharacterSet|DatabaseCollation|DatabaseEncryption|DatabaseReadOnly $option): Tree
    {
        if ($option instanceof DatabaseEncryption) {
            return new Tree('database-encryption', [Build::keyword('ENCRYPTION'), new Atom('literal', "'" . $option->value . "'")]);
        }
        if ($option instanceof DatabaseReadOnly) {
            return new Tree('database-access', [Build::keyword('READ ONLY'), new Atom('literal', $option->value)]);
        }
        return new Tree('database-character-default', [Build::keyword($option instanceof DatabaseCharacterSet ? 'CHARACTER SET' : 'COLLATE'), $option->name instanceof ServerCharacterDefault ? Build::keyword('DEFAULT') : Build::identifier([$option->name], Dialect::MySql)]);
    }
}
