put('src/Binding/Statement/Definition/Storage/RemovalOptions.php',r'''namespace SqlSemantics\Binding\Statement\Definition\Storage;

use SqlParser\Parser\Node;
use SqlSemantics\Ast\Identifiers;
use SqlSemantics\Ast\MySqlNames;
use SqlSemantics\Ast\Tree;
use SqlSemantics\Binding\Statement\UnclassifiedSql;
use SqlSemantics\InvalidSql;
use SqlSemantics\Model\Definition\Storage\CompletionWait;
use SqlSemantics\Model\Validation\InputViolation;

/**
 * Binds storage engine selection and completion policy in their release-specific grammar.
 * @visibility SqlSemantics
 */
final class RemovalOptions
{
    /**
     * Requires at most one engine declaration, including repeated identical names.
     * @throws InvalidSql
     * @throws UnclassifiedSql
     */
    public static function engine(Node $source, Identifiers $identifiers): ?string
    {
        $options = Tree::outer($source, ['ts_option_engine', 'opt_ts_engine']);
        if (count($options) > 1) {
            throw new InvalidSql(InputViolation::StorageOption, $source);
        }
        if ($options === []) {
            return null;
        }
        $name = Tree::outer($options[0], ['ident_or_text'])[0] ?? throw new UnclassifiedSql('A storage engine option requires its name.');
        $engine = MySqlNames::read($name->tokens()[0], $identifiers);
        if ($engine === '') {
            throw new InvalidSql(InputViolation::StorageName, $name);
        }
        return $engine;
    }

    /**
     * Normalizes default waiting and preserves the legacy repeated-NO_WAIT rejection.
     * @throws InvalidSql
     */
    public static function waiting(Node $source): CompletionWait
    {
        $waiting = CompletionWait::Wait;
        foreach (Tree::outer($source, ['ts_option_wait', 'ts_wait']) as $option) {
            $next = CompletionWait::from(strtoupper(Tree::text($option)));
            if ($option->name === 'ts_wait' && $waiting === CompletionWait::NoWait && $next === CompletionWait::NoWait) {
                throw new InvalidSql(InputViolation::StorageOption, $option);
            }
            $waiting = $next;
        }
        return $waiting;
    }
}
''')
put('src/Binding/Statement/Definition/Storage/Removals.php',r'''namespace SqlSemantics\Binding\Statement\Definition\Storage;

use SqlParser\Parser\Node;
use SqlSemantics\Ast\Tree;
use SqlSemantics\Binding\Query\QueryContext;
use SqlSemantics\Binding\Statement\UnclassifiedSql;
use SqlSemantics\Dialect;
use SqlSemantics\InvalidSql;
use SqlSemantics\Model\BoundStatement;
use SqlSemantics\Model\Statement\Definition\MySql\Storage as Statement;
use SqlSemantics\Model\Statement\Origin;
use SqlSemantics\Model\Validation\InputViolation;

/**
 * Binds separate tablespace, undo-tablespace, and logfile-group removal operations.
 * @visibility SqlSemantics
 */
final class Removals
{
    /**
     * Describes storage targets without touching files or expanding engine effects.
     * @throws UnclassifiedSql
     * @throws InvalidSql
     */
    public static function bind(Origin $origin, Node $source, QueryContext $context): ?BoundStatement
    {
        $tokens = $source->tokens();
        $kind = strtoupper($tokens[1]->text ?? '');
        if ($origin->dialect !== Dialect::MySql || strtoupper($tokens[0]->text ?? '') !== 'DROP' || !in_array($kind, ['TABLESPACE', 'LOGFILE', 'UNDO'], true)) {
            return null;
        }
        $name = Tree::child($source, ['ident', 'tablespace_name', 'logfile_group_name']) ?? throw new UnclassifiedSql('Storage removal requires its target name.');
        $identity = $context->tables->identifiers->name($name->tokens()[0]);
        if ($identity === '') {
            throw new InvalidSql(InputViolation::StorageName, $name);
        }
        $engine = RemovalOptions::engine($source, $context->tables->identifiers);
        $waiting = RemovalOptions::waiting($source);
        return match ($kind) {
            'TABLESPACE' => new Statement\DropTablespaceStatement($origin, $identity, $engine, $waiting),
            'LOGFILE' => new Statement\DropLogfileGroupStatement($origin, $identity, $engine, $waiting),
            'UNDO' => new Statement\DropUndoTablespaceStatement($origin, $identity, $engine),
        };
    }
}
''')
